// SPDX-License-Identifier: Apache-2.0
//! `mask` over every Unicode scalar value against the classes Spark 4.2
//! assigned (`tests/fixtures/spark-4.2.0/mask-classes.json`, generated by
//! `tests/scripts/gen_mask_table.py`): upper, lower, digit or other, with a
//! supplementary scalar counting as two other UTF-16 units.
#![forbid(unsafe_code)]

use arrow_array::StringArray;
use krishiv_kernels::string::{StrOperand, mask};
use serde_json::Value;

type R = Result<(), Box<dyn std::error::Error>>;

/// The class Spark assigns to a basic-multilingual-plane scalar.
fn expected(cp: u32, ranges: &[(u32, u32, char)]) -> char {
    if let Some(&(_, _, class)) = ranges.iter().find(|r| r.0 <= cp && cp <= r.1) {
        return class;
    }
    match cp {
        0x41..=0x5A => 'U',
        0x61..=0x7A => 'l',
        0x30..=0x39 => 'd',
        _ => 'o',
    }
}

#[test]
fn every_scalar_is_classified_as_in_spark() -> R {
    let path = krishiv_testkit::tests_dir().join("fixtures/spark-4.2.0/mask-classes.json");
    let fixture: Value = serde_json::from_str(&std::fs::read_to_string(path)?)?;
    let mut ranges = Vec::new();
    for r in fixture["ranges"].as_array().ok_or("ranges")? {
        let first = u32::try_from(r[0].as_u64().ok_or("first")?)?;
        let last = u32::try_from(r[1].as_u64().ok_or("last")?)?;
        let class = r[2]
            .as_str()
            .and_then(|s| s.chars().next())
            .ok_or("class")?;
        ranges.push((first, last, class));
    }
    let scalars: Vec<char> = (0..=0x10_FFFF_u32).filter_map(char::from_u32).collect();
    assert_eq!(
        u64::try_from(scalars.len())?,
        fixture["scalars"].as_u64().unwrap_or(0)
    );
    let strings: Vec<String> = scalars.iter().map(char::to_string).collect();
    let input = StringArray::from_iter_values(&strings);
    let lit = |s| StrOperand::Scalar(Some(s));
    let out = mask(
        StrOperand::Array(&input),
        lit("U"),
        lit("l"),
        lit("d"),
        lit("o"),
    )?;
    let mut bad = Vec::new();
    for (i, c) in scalars.iter().enumerate() {
        let cp = u32::from(*c);
        let want: String = if cp > 0xFFFF {
            "oo".to_owned()
        } else {
            expected(cp, &ranges).to_string()
        };
        if out.value(i) != want {
            bad.push(format!(
                "mask(U+{cp:04X}) = {:?}, Spark {want:?}",
                out.value(i)
            ));
        }
    }
    assert!(
        bad.is_empty(),
        "{} differences, first: {:?}",
        bad.len(),
        &bad[..bad.len().min(20)]
    );
    Ok(())
}
